(()=>{
 const section=document.getElementById('balcao-empregos'); if(!section)return;
 const main=document.querySelector('main'); const navLinks=[...document.querySelectorAll('.topbar nav a[href^="#"]')];
 const normalSections=[...main.children].filter(el=>el!==section);
 function showJobs(on){ section.classList.toggle('hidden',!on); normalSections.forEach(el=>el.classList.toggle('hidden',on)); navLinks.forEach(a=>a.classList.toggle('active',on&&a.getAttribute('href')==='#balcao-empregos')); if(on)window.scrollTo({top:0,behavior:'smooth'}); }
 navLinks.forEach(a=>a.addEventListener('click',e=>{const href=a.getAttribute('href');if(href==='#balcao-empregos'){e.preventDefault();showJobs(true)}else if(href==='#radio'||href==='#mais-tocadas'||href==='#ouvintes'){showJobs(false)}}));
 document.querySelector('.brand')?.addEventListener('click',()=>showJobs(false));
 const form=document.getElementById('jobForm'), status=document.getElementById('jobFormStatus'), list=document.getElementById('jobsList'), count=document.getElementById('jobCount');
 const esc=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 async function loadJobs(){try{const r=await fetch('/api/jobs');const d=await r.json();const jobs=d.jobs||[];count.textContent=jobs.length+' oportunidade'+(jobs.length===1?'':'s');list.innerHTML=jobs.length?jobs.map(j=>`<article class="job-card"><div class="job-photo-stack">${(j.photos&&j.photos.length?j.photos:(j.photo?[j.photo]:[])).map(photo=>`<img src="${photo}" alt="Empresa ${esc(j.company)}">`).join('')||'<div class="job-card-placeholder">🏢</div>'}</div><div><h4>${esc(j.company)}</h4><p class="job-role">${esc(j.role)}</p><div class="job-meta"><span>📍 ${esc(j.location)}</span>${j.salary?`<span>💰 ${esc(j.salary)}</span>`:''}<span>CNPJ: ${esc(j.cnpj)}</span></div>${j.description?`<p class="job-desc">${esc(j.description)}</p>`:''}<a class="job-contact" href="${/^https?:\/\//i.test(j.serverUrl||'')?esc(j.serverUrl):'mailto:'+encodeURIComponent(j.contact)}" target="_blank" rel="noopener">Contato: ${esc(j.contact)}</a><div class="job-social"><button type="button" data-job-like="${esc(j.id)}">♥ <span>${Number(j.likes)||0}</span> Curtir</button><button type="button" data-job-comment="${esc(j.id)}">▢ Comentar / tenho interesse</button></div><div class="job-comments" id="job-comments-${esc(j.id)}"></div></div></article>`).join(''):'<p class="jobs-empty">Ainda não há vagas publicadas. Seja a primeira empresa a anunciar!</p>';list.querySelectorAll('[data-job-like]').forEach(b=>b.onclick=async()=>{try{const r=await fetch('/api/jobs/'+encodeURIComponent(b.dataset.jobLike)+'/like',{method:'POST'});const d=await r.json();if(!r.ok)throw Error(d.error||'Falha');b.querySelector('span').textContent=d.likes}catch(e){status.textContent='Não foi possível registrar a curtida.'}});list.querySelectorAll('[data-job-comment]').forEach(b=>b.onclick=()=>{const box=document.getElementById('job-comments-'+b.dataset.jobComment);if(box.childElementCount)return;const input=document.createElement('input');input.maxLength=300;input.placeholder='Seu nome e mensagem de interesse';const send=document.createElement('button');send.type='button';send.textContent='Enviar comentário';send.onclick=async()=>{if(!input.value.trim())return;try{const r=await fetch('/api/jobs/'+encodeURIComponent(b.dataset.jobComment)+'/comments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:input.value})});const d=await r.json();if(!r.ok)throw Error(d.error||'Falha');box.innerHTML=d.comments.map(c=>`<p>${esc(c.text)}</p>`).join('');}catch(e){status.textContent='Não foi possível enviar o comentário.'}};box.append(input,send);fetch('/api/jobs/'+encodeURIComponent(b.dataset.jobComment)+'/comments').then(r=>r.json()).then(d=>{if(d.comments?.length)box.insertAdjacentHTML('afterbegin',d.comments.map(c=>`<p>${esc(c.text)}</p>`).join(''))}).catch(()=>{})});}catch{list.innerHTML='<p class="jobs-empty">Não foi possível carregar as vagas agora.</p>'}}
 form?.addEventListener('submit',async e=>{e.preventDefault();status.textContent='Publicando vaga…';const photoFiles=[...document.getElementById('jobPhoto').files];let photos=[];if(photoFiles.length>3){status.textContent='Escolha no máximo 3 fotos.';return}for(const file of photoFiles){if(file.size>2*1024*1024){status.textContent='Cada foto deve ter até 2 MB.';return}photos.push(await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)}))}const data={company:document.getElementById('jobCompany').value,cnpj:document.getElementById('jobCnpj').value,role:document.getElementById('jobRole').value,salary:document.getElementById('jobSalary').value,location:document.getElementById('jobLocation').value,contact:document.getElementById('jobContact').value,serverUrl:document.getElementById('jobServer').value,description:document.getElementById('jobDescription').value,photos};try{const r=await fetch('/api/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.error||'Falha ao publicar');form.reset();status.textContent='Vaga publicada com sucesso.';await loadJobs()}catch(err){status.textContent=err.message||'Não foi possível publicar a vaga.'}});

 const photoInput=document.getElementById('jobPhoto');photoInput?.addEventListener('change',()=>{const files=[...photoInput.files];document.getElementById('jobPhotoNames').textContent=files.length?files.map(f=>f.name).join(', '):'Escolha até 3 imagens'});
 loadJobs();
})();
